function server(f,{initial=[],identity=me,get,post}={}){const reviews=[...initial],requests=[],experiments=[f.original,f.reproduction,f.manifest],source=f.source;globalThis.fetch=async(path,init={})=>{requests.push({path,init});const url=new URL(path,'https://local');if(get&&init.method!=='POST'){const v=await get(path,init,reviews);if(v!==undefined)return v instanceof Response?v:Response.json(v);}if(path==='/api/experiments/reviews/me')return Response.json(identity);if(path.startsWith('/api/strategies?')){const item=(f.sources??[source]).find(item=>item.id===url.searchParams.get('id'));return item?Response.json(envelope(item)):new Response(null,{status:404});}if(path.startsWith('/api/experiments?id=')){const item=experiments.find(row=>row.id===url.searchParams.get('id'));return item?Response.json(envelope(item)):new Response(null,{status:404});}if(init.method==='POST'){const command=JSON.parse(init.body);if(post){const v=await post(command,reviews);if(v!==undefined)return v instanceof Response?v:Response.json(v);}if(command.action==='report')return Response.json(receipt(command,null,{requestId:command.requestId,id:command.id,digest:command.digest,reason:command.reason,createdAt:at}));const target=reviews.find(row=>row.id===command.id),value=command.action==='review'?await published(command,(reviews.reduce((n,row)=>Math.max(n,row.sequence),0))+1):command.action==='withdraw'?moderated(target,'WITHDRAWN',command.reason,command.requestId):moderated(target,command.state,command.reason,command.requestId);reviews.unshift(value);return Response.json(receipt(command,value));}if(url.searchParams.has('id')){const item=reviews.find(row=>row.id===url.searchParams.get('id'));return item?Response.json(envelope(item)):new Response(null,{status:404});}return Response.json(list(f.original,reviews));};return {reviews,requests,experiments,source};}
async function ready(h){await h.until(tree=>button(tree,'Prepare human review')&&!button(tree,'Prepare human review').props.disabled);}
async function importDraft(h,draft){h.click('Prepare human review');await h.flush();h.field('Paired review draft JSON',JSON.stringify(draft));await h.flush();h.click('Check paired draft');await h.until('Original report:');}
async function consent(h){for(const name of ['Confirm review input rights','Confirm public review evidence','Accept review policy']){h.field(name,true);await h.flush();}}
async function decision(h,value='REPRODUCED'){h.field('Review decision',value);await h.flush();h.field('Review reason '+(value==='REPRODUCED'?'COMPUTATION_MATCH':value==='DISPUTED'?'COMPUTATION_MISMATCH':'INCOMPLETE_EVIDENCE'),true);await h.flush();if(value==='REPRODUCED'||value==='DISPUTED')for(const key of ['fixedCode','exactInputs','inspectedDifferences','separateOriginalAndReproductionProcesses']){h.field('Attest '+key,true);await h.flush();}h.field('Review note','A careful computational review, preserving the negative result.');await h.flush();}
