test('anonymous exact original review reading requires no identity and preserves adverse computational limits',async()=>{const f=await fixture(),item=await published(f.command),{requests}=server(f,{initial:[item]}),h=harness(f.original,{signedIn:false});await h.until('COMPUTATION_MATCH');h.click('Open review '+item.id);await h.until('Actual controlled synthetic review note.');assert(walk(h.render(),n=>n.type==='a'&&n.props.href==='/strategies?id='+f.source.id+'&digest='+f.source.digest).length);assert(!walk(h.render(),n=>n.type==='a'&&n.props.href==='/strategies?id='+f.source.id).length);assert(!requests.some(r=>r.path.endsWith('/me')));assert(walk(h.render(),n=>n.type==='a'&&n.props.href==='/signin-with-chatgpt?return_to='+encodeURIComponent('/experiments?id='+f.original.id+'&digest='+f.original.digest+'&review='+item.id+'&reviewDigest='+item.digest)).length);assert(text(h.render()).includes('Qualification NONE'));assert(text(h.render()).includes('independence NOT_ESTABLISHED'));assert(text(h.render()).includes('agreement does not establish profitability'));assert(!button(h.render(),'Prepare human review'));assert(!requests.some(r=>r.init.method==='POST'));});

