 const f=await programReviewFixture(),srv=server(f),h=harness(f.original);await ready(h);await importDraft(h,f.draft);assert(text(h.render()).includes('same-implementation generator reconstruction'));assert.equal(field(h.render(),'Review decision').props.value,'HELD');assert.equal(field(h.render(),'Attest fixedCode').props.checked,false);assert.equal(srv.requests.filter(row=>row.init.method==='POST').length,0);await decision(h);await consent(h);h.submit();await h.until('Human review recorded');const post=srv.requests.find(row=>row.init.method==='POST'),command=review.experimentReviewPublishSchema.parse(JSON.parse(post.init.body));assert.equal(command.evidence.method,'PROGRAM_DEMO');assert.deepEqual(command.evidence,f.draft.evidence);assert.equal(command.decision,'REPRODUCED');assert.equal(post.init.headers['X-Experiment-Review-Author'],reviewer.id);assert.equal(f.original.record.classification,'AUTHOR_REPORTED');assert.equal(f.reproduction.record.classification,'AUTHOR_REPORTED');assert.equal(srv.reviews[0].record.qualification,'NONE');assert.equal(srv.reviews[0].record.independence,'NOT_ESTABLISHED');
