async function historyFixture(f,count=25){const rows=[];let previous=null;for(let n=1;n<=count;n++){const id=(n===count?'00000001':n.toString(16).padStart(8,'0'))+'-1111-4111-8111-111111111111',command={...f.command,id,requestId:uid(),previous:previous?ref(previous):null};const row=await published(command,n);rows.push(row);previous=row;}return {rows:rows.sort((a,b)=>b.id.localeCompare(a.id)),head:{...ref(previous),sequence:count}};}

